INSERT INTO `help_topic` (`name`, `body`, `updated_by`) VALUES
('accelerate', 'Usage: cast accelerate [<target>]\n\nA group buff that speeds everyone up. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: the hindpaw from a greyhound\nRelated: skills practice cast pray affects\nApprox. Level: 11\nDiscipline: 32%\nClasses: Mage', 'seed'),
('acid blast', 'Usage: cast acid blast\n\nAn area-effect burst of acid damage. This is an area-effect spell -- it strikes everyone else in the room at once, not a single target.\nRequires: a decanter of fluorinide hydroxate\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 75%\nClasses: Mage', 'seed'),
('advanced berserking', 'An upgraded berserk with a stronger effect.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 20\nDiscipline: 50%\nClasses: Warrior', 'seed'),
('advanced kicking', 'More of your unarmed strikes land as kicks, boosting extra-attack odds.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 25%\nClasses: Monk', 'seed'),
('animate', 'Usage: cast animate [<target>]\n\nAnimates an object to fight for you. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a dragon lich''s tooth\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Mage', 'seed'),
('arctic blast', 'Usage: cast arctic blast\n\nAn area-effect burst of cold damage. This is an area-effect spell -- it strikes everyone else in the room at once, not a single target.\nRequires: an ice pipe\nRelated: skills practice cast pray affects\nApprox. Level: 6\nDiscipline: 16%\nClasses: Mage', 'seed'),
('armor', 'Usage: pray armor [<target>]\n\nA protective blessing that improves armor class. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Cleric', 'seed'),
('astral walk', 'Usage: pray astral walk [<target>]\n\nTravel the astral plane to another location. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 35\nDiscipline: 33%\nClasses: Cleric', 'seed'),
('atomize', 'Usage: cast atomize [<target>]\n\nAn overwhelming single-target burst of energy. This is a single-target spell -- aimed at one person: whoever you name, or whoever you''re already fighting if you don''t name anyone.\nRequires: a vial of powdered dragon bone\nRelated: skills practice cast pray affects\nApprox. Level: 48\nDiscipline: 80%\nClasses: Mage', 'seed'),
('attune', 'Usage: pray attune [<target>]\n\nBind a holy symbol to your faction. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 10%\nClasses: Cleric', 'seed'),
('backstab', 'A devastating sneak attack against an unaware or from-behind target.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Thief', 'seed'),
('barehand proficiency', 'Usage: cast barehand proficiency [<target>], pray barehand proficiency [<target>]\n\nBasic proficiency fighting unarmed. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`); a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Cleric, Druid, Mage', 'seed'),
('barkskin', 'Usage: cast barkskin [<target>]\n\nYour skin turns to bark, granting a strong armor bonus. Targets one person -- you by default, or someone you name.\nRequires: a dollop of petrified syrup\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Druid', 'seed'),
('bash', 'Knock your target down, stunning them briefly.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Warrior', 'seed'),
('beast soother', 'Usage: cast beast soother [<target>]\n\nCalms a hostile or hunting animal. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: some cactus pulp\nRelated: skills practice cast pray affects\nApprox. Level: 5\nDiscipline: 6%\nClasses: Druid', 'seed'),
('berserk', 'Forgo defense for a burst of offense -- but you''re much harder to rescue or parry while raging.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Warrior', 'seed'),
('bind', 'Usage: cast bind [<target>]\n\nWebs a target in place. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a black widow''s web\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Mage', 'seed'),
('blast of fury', 'Usage: cast blast of fury [<target>]\n\nA bolt of raw energy damage. This is a single-target spell -- aimed at one person: whoever you name, or whoever you''re already fighting if you don''t name anyone.\nRequires: the blood of a scorned woman\nRelated: skills practice cast pray affects\nApprox. Level: 31\nDiscipline: 20%\nClasses: Mage', 'seed'),
('bleed', 'Usage: pray bleed [<target>]\n\nOpens a wound that bleeds over time. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Cleric', 'seed'),
('bless', 'Usage: pray bless [<target>]\n\nA blessing that improves hit and damage rolls. This is a single-target spell -- aimed at one person: whoever you name, or whoever you''re already fighting if you don''t name anyone.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Cleric', 'seed'),
('blindfighting', 'Reduces the penalty for fighting while blinded.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Monk', 'seed'),
('blindness', 'Usage: pray blindness [<target>]\n\nBlinds a target. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 21\nDiscipline: 84%\nClasses: Cleric', 'seed'),
('blizzard', 'Usage: cast blizzard\n\nA room-persistent area-effect cold storm. This is an area-effect spell -- it strikes everyone else in the room at once, not a single target.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`)\nRelated: skills practice cast pray affects\nApprox. Level: 39\nDiscipline: 50%\nClasses: Mage', 'seed'),
('blunt proficiency', 'Usage: cast blunt proficiency [<target>], pray blunt proficiency [<target>]\n\nBasic proficiency with blunt weapons. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`); a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Cleric, Druid, Mage', 'seed'),
('blur', 'A chance at an extra unarmed attack each round while empty-handed.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Monk', 'seed'),
('bodyslam', 'A grappling throw that slams your opponent down for damage.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 10\nDiscipline: 30%\nClasses: Warrior', 'seed'),
('bone breaker', 'Usage: pray bone breaker [<target>]\n\nBreaks one of a target''s limbs. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 40\nDiscipline: 51%\nClasses: Cleric', 'seed'),
('bonebreak', 'A high-damage grapple attack that breaks a limb.\nUsage: bonebreak (while fighting). Heavy limb damage plus a lasting Broken Bone affliction -- unless the victim knows iron bones.\nRelated: skills practice cast pray affects\nApprox. Level: 50\nDiscipline: 75%\nClasses: Monk', 'seed'),
('bramble drain', 'Usage: cast bramble drain [<target>]\n\nA thorned vine that drains a small amount of life to you. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`)\nRelated: skills practice cast pray affects\nApprox. Level: 3\nClasses: Druid', 'seed'),
('brawl avoidance', 'Passive resistance to grapple- and trip-style attacks.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 75%\nClasses: Warrior', 'seed'),
('call lightning', 'Usage: pray call lightning [<target>]\n\nCalls down a bolt of lightning. This is a single-target spell -- aimed at one person: whoever you name, or whoever you''re already fighting if you don''t name anyone.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 40\nDiscipline: 51%\nClasses: Cleric', 'seed'),
('calm', 'Usage: cast calm [<target>]\n\nPacifies a target, stopping violence. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: an olive branch\nRelated: skills practice cast pray affects\nApprox. Level: 19\nDiscipline: 58%\nClasses: Mage', 'seed'),
('catfall', 'Halves damage from a fall.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Monk', 'seed'),
('catleap', 'Leap and glide a direction, out of combat.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Monk', 'seed'),
('chain attack', 'A chance at a bonus follow-up strike each round.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Monk', 'seed'),
('chain lightning', 'Usage: cast chain lightning [<target>]\n\nA bolt of lightning that arcs between targets. This is a single-target spell -- aimed at one person: whoever you name, or whoever you''re already fighting if you don''t name anyone.\nRequires: a tiny glowing spark\nRelated: skills practice cast pray affects\nApprox. Level: 48\nDiscipline: 60%\nClasses: Mage', 'seed'),
('charge stave', 'Usage: cast charge stave [<target>]\n\nCharges a magical stave. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`)\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Mage', 'seed'),
('chi', 'A chi-powered strike against a foe.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Monk', 'seed'),
('chop', 'An edge-of-hand strike.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 51%\nClasses: Monk', 'seed'),
('cintai', 'A passive to-hit bonus.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 5\nDiscipline: 5%\nClasses: Monk', 'seed'),
('close quarters fighting', 'A combat bonus while grappled or fighting at point-blank range.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 50\nDiscipline: 85%\nClasses: Warrior', 'seed'),
('clot', 'Usage: cast clot [<target>], pray clot [<target>]\n\nStops a victim''s bleeding. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`); a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 2\nDiscipline: 16%\nClasses: Cleric, Druid', 'seed'),
('cloud of concealment', 'Usage: cast cloud of concealment [<target>]\n\nFills the room with concealing mist. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a prism of condensation\nRelated: skills practice cast pray affects\nApprox. Level: 31\nDiscipline: 20%\nClasses: Mage', 'seed'),
('color spray', 'Usage: cast color spray\n\nAn area-effect burst of damage that can blind. This is an area-effect spell -- it strikes everyone else in the room at once, not a single target.\nRequires: a rainbow stone\nRelated: skills practice cast pray affects\nApprox. Level: 12\nDiscipline: 35%\nClasses: Mage', 'seed'),
('concealment', 'Hide your movement trail from trackers. Passive -- while you know it, a mortal's `track` can't follow your trail (it goes cold).\nRequires: passive -- no command to invoke\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Thief', 'seed'),
('conjure elemental air', 'Usage: cast conjure elemental air [<target>]\n\nSummons an air elemental ally. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: some pieces of cloud stone\nRelated: skills practice cast pray affects\nApprox. Level: 12\nDiscipline: 35%\nClasses: Mage', 'seed'),
('conjure elemental earth', 'Usage: cast conjure elemental earth [<target>]\n\nSummons an earth elemental ally. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a piece of lichstone\nRelated: skills practice cast pray affects\nApprox. Level: 21\nDiscipline: 63%\nClasses: Mage', 'seed'),
('conjure elemental fire', 'Usage: cast conjure elemental fire [<target>]\n\nSummons a fire elemental ally. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a star sapphire\nRelated: skills practice cast pray affects\nApprox. Level: 19\nDiscipline: 57%\nClasses: Mage', 'seed'),
('conjure elemental water', 'Usage: cast conjure elemental water [<target>]\n\nSummons a water elemental ally. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a turquoise waterstone\nRelated: skills practice cast pray affects\nApprox. Level: 24\nDiscipline: 71%\nClasses: Mage', 'seed'),
('consecrate', 'Usage: pray consecrate [<target>]\n\nFills the room with a persistent holy effect. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 43\nDiscipline: 60%\nClasses: Cleric', 'seed'),
('copy', 'Usage: cast copy [<target>]\n\nDuplicates an item. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: some doppleganger''s skin\nRelated: skills practice cast pray affects\nApprox. Level: 23\nDiscipline: 70%\nClasses: Mage', 'seed'),
('counter move', 'Resist being shoved or thrown out of position.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 50%\nClasses: Monk', 'seed'),
('counter steal', 'A passive chance to catch someone trying to steal from you.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Thief', 'seed'),
('create food', 'Usage: cast create food [<target>], pray create food [<target>]\n\nConjures food from nothing. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`); a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 3\nDiscipline: 11%\nClasses: Cleric, Druid', 'seed'),
('create water', 'Usage: cast create water [<target>], pray create water [<target>]\n\nFills a container with water. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`); a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 3\nDiscipline: 11%\nClasses: Cleric, Druid', 'seed'),
('critical hitting', 'Improves your access to the harshest critical-hit outcomes.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Monk', 'seed'),
('crusade', 'Usage: pray crusade [<target>]\n\nA group-wide blessing for everyone in the room. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 49\nDiscipline: 80%\nClasses: Cleric', 'seed'),
('cudgel', 'A blunt, non-lethal knockout-style attack.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 41\nDiscipline: 66%\nClasses: Thief', 'seed'),
('cure blindness', 'Usage: cast cure blindness [<target>], pray cure blindness [<target>]\n\nRemoves blindness from a victim. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`); a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 12\nDiscipline: 45%\nClasses: Cleric, Druid', 'seed'),
('cure disease', 'Usage: cast cure disease [<target>], pray cure disease [<target>]\n\nRemoves disease from a victim. Targets one person -- you by default, or someone you name.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`); a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 8\nDiscipline: 30%\nClasses: Cleric, Druid', 'seed'),
('cure paralysis', 'Usage: pray cure paralysis [<target>]\n\nRemoves paralysis from a victim. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 37\nDiscipline: 40%\nClasses: Cleric', 'seed'),
('cure poison', 'Usage: cast cure poison [<target>], pray cure poison [<target>]\n\nRemoves poison from a victim. Targets one person -- you by default, or someone you name.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`); a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 3\nDiscipline: 11%\nClasses: Cleric, Druid', 'seed'),
('curse', 'Usage: pray curse [<target>]\n\nCurses a target or object. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 13\nDiscipline: 51%\nClasses: Cleric', 'seed'),
('deathstroke', 'A heavy, finishing-style attack against a single target.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 20\nDiscipline: 51%\nClasses: Warrior', 'seed'),
('defenestrate', 'Throw a victim through a window into another room.\nUsage: defenestrate (while fighting). A leverage throw that slams your opponent to the ground and costs them a round.\nRelated: skills practice cast pray affects\nApprox. Level: 42\nDiscipline: 50%\nClasses: Monk', 'seed'),
('detect invisibility', 'Usage: cast detect invisibility [<target>]\n\nLets you see invisible things. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: an eclipse heart\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Mage', 'seed'),
('detect magic', 'Usage: cast detect magic [<target>]\n\nLets you see magical auras. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: some athanor dust\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 1%\nClasses: Mage', 'seed'),
('detect trap', 'Spot a trap before it triggers.\nRequires: not applicable -- this is a real command, see `search`\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Thief', 'seed'),
('devotion', 'Usage: pray devotion [<target>]\n\nPassive prayer-point regeneration. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Cleric', 'seed'),
('disarm', 'Knock the weapon out of an opponent''s hand.\nRequires: not applicable -- this is a real command, see `disarm`\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 33%\nClasses: Monk, Thief, Warrior', 'seed'),
('disarm trap', 'Safely disable a trap you''ve detected.\nRequires: not applicable -- this is a real command, see `disarmtrap`\nRelated: skills practice cast pray affects\nApprox. Level: 25\nDiscipline: 33%\nClasses: Thief', 'seed'),
('disguise', 'Alter your apparent identity.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Thief', 'seed'),
('dispel invisible', 'Usage: cast dispel invisible [<target>]\n\nReveals an invisible target. Strips the AFFECT_INVISIBLE affect from yourself by default, or an ally you name; says so plainly if the target is already visible.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`)\nRelated: skills practice cast pray affects\nApprox. Level: 17\nDiscipline: 50%\nClasses: Mage', 'seed'),
('dispel magic', 'Usage: cast dispel magic [<target>]\n\nStrips magical effects from a being or object. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a white-metal magnet\nRelated: skills practice cast pray affects\nApprox. Level: 20\nDiscipline: 61%\nClasses: Mage', 'seed'),
('divination', 'Usage: cast divination [<target>]\n\nReveals information about an object or being. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a crystal ball\nRelated: skills practice cast pray affects\nApprox. Level: 45\nDiscipline: 68%\nClasses: Mage', 'seed'),
('dodge', 'A passive chance to evade incoming melee attacks; the more you fight, the better you get at it.\nRequires: passive -- no command to invoke\nRelated: skills practice affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Thief', 'seed'),
('doorbash', 'Charge a closed -- even locked -- door and force it open by brute strength, no key needed. Fail and you bounce off, bruised.\nUsage: doorbash <direction>\nRelated: skills practice open affects\nApprox. Level: 1\nDiscipline: 1%\nClasses: Warrior', 'seed'),
('dual wield', 'Passively reduces the damage penalty for your off-hand weapon.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 1\nDiscipline: 50%\nClasses: Thief, Warrior', 'seed'),
('dufali', 'Passive resistance to paralysis.\nRequires: nothing yet -- not implemented as a command\nRelated: skills practice cast pray affects\nApprox. Level: 48\nDiscipline: 70%\nClasses: Monk', 'seed'),
('dust storm', 'Usage: cast dust storm\n\nAn area-effect burst of wind and grit damage. This is an area-effect spell -- it strikes everyone else in the room at once, not a single target.\nRequires: a decanter of vaporous quartz\nRelated: skills practice cast pray affects\nApprox. Level: 11\nDiscipline: 33%\nClasses: Mage', 'seed'),
('earthmaw', 'Usage: cast earthmaw [<target>]\n\nThe ground splits beneath a target, damaging and knocking them down -- outdoors only. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`)\nRelated: skills practice cast pray affects\nApprox. Level: 28\nDiscipline: 41%\nClasses: Druid', 'seed'),
('earthquake', 'Usage: pray earthquake [<target>]\n\nA room-wide tremor that damages everyone in it. This is a single-target spell -- aimed at one person: whoever you name, or whoever you''re already fighting if you don''t name anyone.\nRequires: a holy symbol -- any item keyworded "symbol" (e.g., a wooden holy symbol) (`pray`)\nRelated: skills practice cast pray affects\nApprox. Level: 33\nDiscipline: 26%\nClasses: Cleric', 'seed'),
('energy drain', 'Usage: cast energy drain [<target>]\n\nDrains a resource from a target while damaging them. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: the wing of a vampire bat\nRelated: skills practice cast pray affects\nApprox. Level: 36\nDiscipline: 40%\nClasses: Mage', 'seed'),
('enhance weapon', 'Usage: cast enhance weapon [<target>]\n\nPermanently enchants a weapon. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a tiny bag of diamond dust\nRelated: skills practice cast pray affects\nApprox. Level: 24\nDiscipline: 72%\nClasses: Mage', 'seed'),
('ensorcer', 'Usage: cast ensorcer [<target>]\n\nCharms or dominates a target. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: a bit of siren''s hair\nRelated: skills practice cast pray affects\nApprox. Level: 15\nDiscipline: 43%\nClasses: Mage', 'seed'),
('entangling roots', 'Usage: cast entangling roots [<target>]\n\nRoots erupt underfoot, tripping and damaging a target -- only works outdoors. Not yet wired to a real effect -- consumes its component/symbol and does nothing further yet.\nRequires: any item keyworded "component" (e.g., a pouch of spell components) (`cast`)\nRelated: skills practice cast pray affects\nApprox. Level: 1\nClasses: Druid', 'seed'),
